SELECT CASE WHEN store_sales.units >= 36 THEN 'high' WHEN store_sales.units >= 7 THEN 'mid' ELSE 'low' END AS units_bucket, MAX(inventory.quantity) AS max_quantity FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id GROUP BY CASE WHEN store_sales.units >= 36 THEN 'high' WHEN store_sales.units >= 7 THEN 'mid' ELSE 'low' END ORDER BY units_bucket LIMIT 1;
